## What Problem This Solves

Fixes an issue where malformed browser audio frames sent through Talk realtime or transcription relays could be silently decoded and forwarded to provider audio streams.

## Why This Change Was Made

The relay now canonicalizes `audioBase64` before decoding it and rejects malformed frames before creating input-audio events or sending bytes to realtime/STT providers.

## User Impact

Talk relays fail closed on malformed audio frames instead of passing corrupted audio into provider sessions.

## Evidence

- Real module proof imported the changed relay entry points and sent `not-base64!`; both relays rejected it before provider delivery.

```text
$ node --import tsx --input-type=module - < proof-live.mjs
realtime-error=Realtime relay audio frame is invalid base64
realtime-provider-audio=0
realtime-input-events=0
transcription-error=Transcription Talk audio frame is invalid base64
transcription-provider-audio=0
transcription-input-events=0
```

<details>
<summary>proof-live.mjs</summary>

```js
import {
  createTalkRealtimeRelaySession,
  sendTalkRealtimeRelayAudio,
  stopTalkRealtimeRelaySession,
} from "./src/gateway/talk-realtime-relay.ts";
import {
  createTalkTranscriptionRelaySession,
  sendTalkTranscriptionRelayAudio,
  stopTalkTranscriptionRelaySession,
} from "./src/gateway/talk-transcription-relay.ts";

const events = [];
const context = {
  getRuntimeConfig: () => ({}),
  broadcastToConnIds: (event, payload, connIds) =>
    events.push({ event, payload, connIds: [...connIds] }),
};
const realtimeAudio = [];
const realtime = createTalkRealtimeRelaySession({
  context,
  connId: "conn-1",
  provider: {
    id: "proof-realtime",
    label: "Proof Realtime",
    isConfigured: () => true,
    createBridge: () => ({
      connect: async () => undefined,
      sendAudio: (audio) => realtimeAudio.push(audio),
      setMediaTimestamp: () => undefined,
      handleBargeIn: () => undefined,
      submitToolResult: () => undefined,
      acknowledgeMark: () => undefined,
      close: () => undefined,
      isConnected: () => true,
    }),
  },
  providerConfig: {},
  instructions: "proof",
  tools: [],
});
await Promise.resolve();
events.length = 0;
try {
  sendTalkRealtimeRelayAudio({
    relaySessionId: realtime.relaySessionId,
    connId: "conn-1",
    audioBase64: "not-base64!",
  });
} catch (error) {
  console.log(`realtime-error=${error instanceof Error ? error.message : String(error)}`);
}
console.log(`realtime-provider-audio=${realtimeAudio.length}`);
console.log(
  `realtime-input-events=${events.filter((entry) => entry.payload?.type === "inputAudio").length}`,
);
stopTalkRealtimeRelaySession({ relaySessionId: realtime.relaySessionId, connId: "conn-1" });

events.length = 0;
const sttAudio = [];
const transcription = createTalkTranscriptionRelaySession({
  context,
  connId: "conn-1",
  provider: {
    id: "proof-stt",
    label: "Proof STT",
    isConfigured: () => true,
    createSession: () => ({
      connect: async () => undefined,
      sendAudio: (audio) => sttAudio.push(audio),
      close: () => undefined,
      isConnected: () => true,
    }),
  },
  providerConfig: {},
});
await Promise.resolve();
events.length = 0;
try {
  sendTalkTranscriptionRelayAudio({
    transcriptionSessionId: transcription.transcriptionSessionId,
    connId: "conn-1",
    audioBase64: "not-base64!",
  });
} catch (error) {
  console.log(`transcription-error=${error instanceof Error ? error.message : String(error)}`);
}
console.log(`transcription-provider-audio=${sttAudio.length}`);
console.log(
  `transcription-input-events=${events.filter((entry) => entry.payload?.type === "inputAudio").length}`,
);
stopTalkTranscriptionRelaySession({
  transcriptionSessionId: transcription.transcriptionSessionId,
  connId: "conn-1",
});
```

